from plan_common import *
import csv,hashlib,re

def csvout(path,headers,rows):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('w',newline='') as f:w=csv.writer(f);w.writerow(headers);w.writerows(rows)
log=[json.loads(s) for s in (ROOT/'analysis/reference/browser_session.jsonl').read_text().splitlines()]
session=1;prev=-1;captures=[]
for e in log:
 if e['elapsedSeconds']<prev:session+=1
 prev=e['elapsedSeconds'];e['sessionId']=f'RUN-{session:02d}'
 if e['command']['op']=='snapshot':
  p=e['result']['screenshot'];captures.append({'captureId':f'CAP-{len(captures)+1:03d}','name':e['command']['name'],'sessionId':e['sessionId'],'elapsedSeconds':e['elapsedSeconds'],'file':p,'sha256':hashlib.sha256((ROOT/p).read_bytes()).hexdigest()})
dump('analysis/reference/captures.json',captures)
dump('analysis/reference/session_timeline.json',log)
byname={c['name']:c for c in captures}
def source(name):return byname[name]['file']
def stamp(name):
 c=byname[name];return f'{c["sessionId"]} t={c["elapsedSeconds"]:.3f}s; {c["captureId"]}'

